mapper.select:
SELECT 
FROM (
    SELECT 
    FROM product_daily_candles
    WHERE product_id = #{productId}
    ORDER BY trade_date DESC
    LIMIT #{count}
) recent
ORDER BY trade_date ASC

SELECT c.product_daily_candle_id, c.product_id, c.trade_date, c.open_price, c.high_price, c.low_price, c.close_price, c.volume, c.currency, c.adjusted, c.source_type, c.source_reference_at, c.created_at, c.updated_at FROM product_daily_candles c JOIN ( SELECT product_id, MAX(trade_date) AS trade_date FROM product_daily_candles WHERE product_id IN
#{productId}
GROUP BY product_id ) latest ON latest.product_id = c.product_id AND latest.trade_date = c.trade_date
